describe('sumUsage', () => {
  it('adds each token field of two reported rounds', () => {
    expect(
      sumUsage({inputTokens: 2, outputTokens: 1, totalTokens: 3}, {inputTokens: 7, outputTokens: 4, totalTokens: 11})
    ).toEqual({inputTokens: 9, outputTokens: 5, totalTokens: 14});
  });

  it('keeps a round that reported nothing from changing the total', () => {
    const total = {inputTokens: 2, outputTokens: 1, totalTokens: 3};

    expect(sumUsage(total, undefined)).toEqual(total);
    expect(sumUsage(undefined, total)).toEqual(total);
  });

  it('stays undefined while no round has reported usage', () => {
    expect(sumUsage(undefined, undefined)).toBeUndefined();
  });
});
