// A round that reported nothing leaves the turn's total as it was; only a turn no round reported stays undefined.
export function sumUsage(total: UsageMetadata | undefined, round: UsageMetadata | undefined): UsageMetadata | undefined {
  if (total === undefined) return round;
  if (round === undefined) return total;
  return {
    inputTokens: total.inputTokens + round.inputTokens,
    outputTokens: total.outputTokens + round.outputTokens,
    totalTokens: total.totalTokens + round.totalTokens,
  };
}
